script.setup:
// Trianglify makes a low-poly pattern: jittered grid points, Delaunay triangles and a colour
// for each triangle from a ColorBrewer gradient. The scene keeps its triangles and colours,
// sways the points and lights each facet from the pointer.
// The browser bundle is self-contained (the package entry wants node-canvas).
const mod = await ctx.utils.import("https://esm.sh/trianglify@4.1.1/dist/trianglify.bundle.js");
const trianglify = mod.default ?? mod;
const gl = ctx.gl;
gl.getExtension("EXT_color_buffer_float");
const flat = ctx.utils.createProgram(`#version 300 es
layout(location=0) in vec2 a_position; layout(location=1) in vec4 a_color;
uniform vec2 u_px; out vec4 v_color;
void main(){ v_color = a_color; gl_Position = vec4(a_position / u_px * 2.0 - 1.0, 0.0, 1.0); }`, `#version 300 es
precision highp float; in vec4 v_color; out vec4 outColor;
void main(){ outColor = v_color; }`);
const vao = gl.createVertexArray(), vbo = gl.createBuffer();
gl.bindVertexArray(vao); gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 24, 0);
gl.enableVertexAttribArray(1); gl.vertexAttribPointer(1, 4, gl.FLOAT, false, 24, 8);
gl.bindVertexArray(null);
const kit = {
  // Draws a flat (x, y, r, g, b, a) triangle list.
  draw(arr) {
    if (!arr.length) return;
    gl.useProgram(flat);
    ctx.utils.setUniforms(flat, { u_px: ctx.resolution });
    gl.bindVertexArray(vao); gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(arr), gl.DYNAMIC_DRAW);
    gl.drawArrays(gl.TRIANGLES, 0, arr.length / 6);
    gl.bindVertexArray(null);
  },
  // Signed triangle fan: inside a closed ring the triangles add up to ±c, outside they cancel.
  // Summed with additive blending, this fills any polygon (holes, self-overlaps) exactly.
  fan(ring, c, out) {
    const x0 = ring[0], y0 = ring[1];
    for (let i = 2; i + 3 < ring.length; i += 2) {
      const s = Math.sign((ring[i] - x0) * (ring[i + 3] - y0) - (ring[i + 1] - y0) * (ring[i + 2] - x0));
      if (!s) continue;
      out.push(x0, y0, c[0] * s, c[1] * s, c[2] * s, c[3] * s,
        ring[i], ring[i + 1], c[0] * s, c[1] * s, c[2] * s, c[3] * s,
        ring[i + 2], ring[i + 3], c[0] * s, c[1] * s, c[2] * s, c[3] * s);
    }
  },
  // Thick polyline as quads (WebGL lines are 1 px); square ends overlap at the joints.
  line(pts, closed, width, c, out) {
    const n = pts.length / 2, hw = width / 2;
    for (let i = 0; i < (closed ? n : n - 1); i++) {
      const j = (i + 1) % n;
      const ax = pts[i * 2], ay = pts[i * 2 + 1], bx = pts[j * 2], by = pts[j * 2 + 1];
      const len = Math.hypot(bx - ax, by - ay);
      if (len < 1e-6) continue;
      const dx = (bx - ax) / len * hw, dy = (by - ay) / len * hw;
      const p = [ax - dx - dy, ay - dy + dx, ax - dx + dy, ay - dy - dx, bx + dx + dy, by + dy - dx, bx + dx - dy, by + dy + dx];
      for (const k of [0, 1, 2, 0, 2, 3]) out.push(p[k * 2], p[k * 2 + 1], c[0], c[1], c[2], c[3]);
    }
  },
  // Disc made of triangles.
  dot(x, y, r, c, out, seg = 16) {
    for (let i = 0; i < seg; i++) {
      const a0 = i / seg * 6.2832, a1 = (i + 1) / seg * 6.2832;
      out.push(x, y, ...c, x + Math.cos(a0) * r, y + Math.sin(a0) * r, ...c, x + Math.cos(a1) * r, y + Math.sin(a1) * r, ...c);
    }
  },
  acc: null,
  // Renders signed fans additively into a half-float target at up to 2x the canvas size
  // (sampling it back with linear filtering smooths the edges). Returns the texture.
  accumulate(arr) {
    const [w, h] = ctx.resolution, k = Math.min(2, 4096 / Math.max(w, h));
    const tw = Math.round(w * k), th = Math.round(h * k);
    if (!kit.acc) kit.acc = ctx.utils.createPingPong(tw, th, { internalFormat: gl.RGBA16F, format: gl.RGBA, type: gl.HALF_FLOAT });
    else if (kit.acc.width !== tw || kit.acc.height !== th) kit.acc.resize(tw, th);
    const t = kit.acc.read();
    gl.bindFramebuffer(gl.FRAMEBUFFER, t.framebuffer); gl.viewport(0, 0, tw, th);
    gl.clearColor(0, 0, 0, 0); gl.clear(gl.COLOR_BUFFER_BIT);
    gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE);
    kit.draw(arr);
    gl.disable(gl.BLEND);
    gl.bindFramebuffer(gl.FRAMEBUFFER, null); gl.viewport(0, 0, w, h);
    return t.texture;
  },
};
const s = ctx.state;
Object.assign(s, { kit, trianglify, key: "", moved: false, light: [0.5, 0.5] });
s.palettes = ["YlGnBu", "RdPu", "Spectral", "PuOr", "YlOrRd", "RdYlBu", "BuPu", "PiYG"];

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, kit = s.kit;
const [w, h] = ctx.resolution, t = ctx.time * u.u_speed;
// Regenerate when the canvas or a pattern option changes.
const key = [w, h, u.u_cell, u.u_variance, u.u_palette, u.u_seed].join();
if (key !== s.key) {
  s.key = key;
  const pal = s.palettes[u.u_palette % s.palettes.length];
  const pattern = s.trianglify({ width: w, height: h, cellSize: u.u_cell * h, variance: u.u_variance, seed: u.u_seed, xColors: pal, yColors: "match" });
  s.points = pattern.points;
  s.polys = pattern.polys.map((p) => ({ idx: p.vertexIndices, color: p.color.gl() }));
  // A height per point (for the facet normals) and a phase for the sway.
  s.extra = s.points.map(() => [Math.random(), Math.random() * 6.283, Math.random() * 6.283]);
  ctx.publish("triangles", s.polys.length);
}
const [mx, my] = ctx.mouse;
s.moved ||= mx !== 0.5 || my !== 0.5;
// The light follows the pointer (eased); before the pointer moves it circles.
const target = s.moved ? [mx, 1 - my] : [0.5 + 0.35 * Math.cos(ctx.time * 0.4), 0.5 + 0.3 * Math.sin(ctx.time * 0.5)];
s.light[0] += (target[0] - s.light[0]) * 0.1; s.light[1] += (target[1] - s.light[1]) * 0.1;
const amp = u.u_sway * u.u_cell * h * 0.25, depth = u.u_cell * h * u.u_depth;
const P = s.points.map(([x, y], i) => {
  const e = s.extra[i];
  return [x + Math.sin(t + e[1]) * amp, h - (y + Math.cos(t * 0.8 + e[2]) * amp), e[0] * depth * (0.8 + 0.2 * Math.sin(t * 0.6 + e[1]))];
});
const L = [s.light[0] * w, s.light[1] * h, h * 0.35];
const tris = [];
for (const p of s.polys) {
  const [a, b, c] = p.idx.map((i) => P[i]);
  // Facet normal from the three lifted points.
  const ux = b[0] - a[0], uy = b[1] - a[1], uz = b[2] - a[2], vx = c[0] - a[0], vy = c[1] - a[1], vz = c[2] - a[2];
  let nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx;
  const nl = Math.hypot(nx, ny, nz) * Math.sign(nz || 1);
  nx /= nl; ny /= nl; nz /= nl;
  const cx = (a[0] + b[0] + c[0]) / 3, cy = (a[1] + b[1] + c[1]) / 3, cz = (a[2] + b[2] + c[2]) / 3;
  let lx = L[0] - cx, ly = L[1] - cy, lz = L[2] - cz;
  const ll = Math.hypot(lx, ly, lz); lx /= ll; ly /= ll; lz /= ll;
  const diff = Math.max(0, nx * lx + ny * ly + nz * lz);
  // Blinn-Phong highlight, viewer straight above.
  const hl = Math.hypot(lx, ly, lz + 1);
  const spec = Math.pow(Math.max(0, (nx * lx + ny * ly + nz * (lz + 1)) / hl), 40) * u.u_shine;
  const near = Math.exp(-ll * ll / (h * h * 0.5));
  const k = 0.45 + 0.75 * diff * (0.6 + 0.4 * near);
  const col = [p.color[0] * k + spec, p.color[1] * k + spec, p.color[2] * k + spec, 1];
  tris.push(a[0], a[1], ...col, b[0], b[1], ...col, c[0], c[1], ...col);
}
gl.clearColor(0, 0, 0, 1); gl.clear(gl.COLOR_BUFFER_BIT);
kit.draw(tris);
